              text: "논리적으로 발생하는 오류 중에 ‘긍정의 오류’와 ‘부정의 오류’라는 것이 있다. 긍정의 오류는 어떤 대상이 존재하지 않음에도 불구하고 그 대상이 존재한다고 판단하는 오류이다. 부정의 오류는 반대로 어떤 대상이 존재함에도 그 대상이 존재하지 않는다고 판단하는 오류이다. 긍정의 오류와 부정의 오류는 현재 발생하였거나 앞으로 발생할 위험에 대처하기 위하여 정책을 세우는 과정에서 발생할 수 있다. 논리학적으로 부정은 반대를 포괄하는 넓은 개념이다. 반대는 ‘0 아니면 1이다’라는 방식으로 명제를 부정하는 것이다. 이는 배중률에 의해 참 또는 거짓의 진리값 만을 가지며, 흑백논리에 빠질 수 있다. 이에 반해 명제를 부정하는 방식으로는 ‘0이 아닐 수도 있다’는 것도 가능하다. 이는 참 또는 거짓뿐 아니라 불가지의 영역을 인정하는 것이다. 즉 참과 거짓 사이 다양한 스펙트럼이 존재한다고 보는 입장이다. 예를 들어, “기후변화의 원인은 확실히 기술이다.”의 반대는 “기후변화의 원인은 확실히 기술이 아니다.”이고, 부정은 “기후변화의 원인이 기술임은 확실하지 않다.”이다. 과학에서도 이러한 영역을 받아들이는 모습을 관찰할 수 있다. 과학적 가설이 세워지면 이를 뒷받침하거나 이를 부정하는 근거들이 발견된다. 가설을 뒷받침하는 증거가 부족하다는 것은, 해당 가설이 틀렸다는 것이 아니라 해당 가설이 확실히 참은 아니라는 것이다. 이때 특정 가설이 참이 아닐 수 있는 근거를 찾는 것은, 특정 가설에 반대하는 근거를 발견하는 것과 다르다. 결과적으로 과학적으로 참에 가까운 가설들이 받아들여지고, 이에 기초하여 정책 역시 설계된다. 이때 사안마다 참으로 받아들일 확률적 한계선을 설정할 수 있다. 가령 제약회사에서 개발한 의약품을 승인하는 것과 같이 인간의 생명과 직결되는 경우에는 발생할 수 있는 오류를 최소화하는 확률적 한계선을 설정할 수 있다. 특정 가설이 100% 완전한 참으로 받아들여질 때까지 행동하지 않는다면 우리는 어떠한 행동도 할 수 없게 될 것이다.",
