              text: "거짓말과 헛소리의 공통점은 부정확한 전달 혹은 기만의 양상이다. 사람들은 헛소리에 더 관대하다. 거짓말은 의도적이다. 거짓말하는 사람은 진실을 어느 정도 알고 있다는 점에서 진실을 존중하는 편이다. 그러므로 헛소리가 더 진실의 적이다. 헛소리는 자신이 내뱉는 말이 진실이든 아니든 개의치 않기 때문이다. 헛소리는 특히 공적 사안에서 심하게 나타난다. 헛소리가 나타나는 이유는 첫째, 사람들이 객관적 진실이나 진리가 존재한다는 믿음을 잃어버렸기 때문이다. 둘째, 사람들이 자신의 분야를 넘어서는 지식에 대해 말하기 때문이다. 이러한 믿음은 일정 부분 민주시민은 모든 공적인 분야에 대해 알아야 한다는 생각에 근거한다. 사람들은 진실을 찾기보다 솔직함이라는 낮은 수준에 만족하고 있다. 진리란 존재하지 않기 때문에 솔직하게 자신의 감정이나 생각을 드러내면 족하다고 생각하는 것이다. 그러나 다른 것은 정확하게 모르면서 자신의 생각이나 감정은 정확하게 알 수 있다는 주장이야말로 헛소리에 불과하다.",
