              text: "“혀에 단맛을 감지하는 미뢰가 많은 사람은 단맛을 더 잘 느낀다.” 이것은 옳은 명제처럼 느껴진다. 그러나 실제 “혀에 단맛을 감지하는 미뢰가 많은 사람은 단맛을 더 잘 느끼는지에 대해 정당한 답변은 무엇인가?”라고 누군가가 묻는다면, 나는 이렇게 말할 수밖에 없다. “그것은 무엇을 증거로 삼는가에 따라 다르다.”라고. 연구의 설계와 연구방식에 따라, 무엇이 정당한 답변인지에 대해서 다른 의견이 존재할 수 있다. 이를테면 이런 사례는 정당한가? 어떤 조직에서는 리더와 팔로어를 선발하기 위하여, 어떤 사람에게 리더의 위치를 부여하고 다른 사람에게는 팔로어의 위치를 부여한 뒤에 뇌를 MRI로 스캔하였다. 그 결과 언어기능과 관련하여 리더의 위치를 부여받았을 때 활성화되는 부분과 팔로어의 위치를 부여받았을 때 활성화되는 부분이 다르다는 사실이 밝혀졌다. 이 결과는 수차례 다른 실험에 의해서 입증되었고, 이 조직은 이러한 연구결과에 따라 조직원들의 뇌 검사 결과를 리더와 팔로어를 선발하는 데에 활용하였다. 다른 사례를 들어볼 수도 있다. 20대 중반 이하의 청년, 소년들은 반사회적, 충동적 행동을 억제해줄 수 있는 전두엽 발달이 부족하다는 것이 인지심리학적으로 입증되어 있다. 이러한 인지심리학적인 결과를 판사나 배심원들은 반영하여, 청년이나 소년들의 범죄에 낮은 형량을 가할 때 논거로서 활용한다. 이것은 과연 정당한가?",
