              no: 4,
              kind: "prose",
              text: "도덕이나 주의(主義)의 표준은 어디에서 오는가? 시비에서 오는가? 이해에서 오는가? 도덕의 표준이 시비에서 나오는 것이라고 해보자. 인간은 각종 동물을 죽이고, 자연을 파괴하고 약탈하고 있으므로 도덕의 기준이 시비라면 인간은 가장 먼저 멸절되어야 할 대상이다. 그렇다면 결국 남는 것은 이해이다. 이해는 시대에 따라서 대소, 광협이 있긴 해도 이해는 이해이다. 그런데 도덕의 표준이 이해라면 사람들은 항상 손해를 싫어하고 이득만을 추구해야 할 것이다. 그렇다면 일진회와 같이 나라를 팔아먹고 노예와 같은 삶을 사는 것 또한 긍정해야 하는가? 그렇지 않다. 이들이 보전하려고 하는 이해는 단시안적인 이해이다. 그것이 장기적인 관점에서 진정한 이해가 아님은 명백하며, 그들의 행위는 그들의 나라에 아무런 이득도 되지 않는다.",
