              text: "인간의 도덕적 행위를 평가하기 위해서는 자유의지에 대한 판단이 필요하다. 모든 행위와 사건에는 원인이 있다는 결정론과 인간의 책임은 양립이 불가능하다. 인간은 도덕적인 행위를 할 수 있는 행위자로서, 자신의 행동과 의사결정에 대한 통제가 가능하며 의지를 결과로 실현할 수 있는 존재이다. 자유로운 인간의 행위는 도덕적 판단이 가능하다. 결정론적 판단에 따라 과거의 원리가 미래를 결정하는 상황에서는 인간 행위의 자유에 따른 주체성을 논할 수 없다. 결정론을 부정하고 자유의지를 긍정하게 되면 인간의 선택에 따라 결과의 차이가 발생한다. 개인에게 도덕적인 책임을 물을 수 있는 배경에는 인간이 자유로운 존재라는 가정이 있고 사회적, 도덕적 삶의 전제와 결론은 자유로운 인간이다. 따라서 결정론을 받아들이는 것이 아니라 개인의 행위에 대한 책임을 인정해야 한다. 도덕적 행위자인 인간은 자신의 행동에 윤리적, 도덕적인 책임을 질 수 있다.",
